SELECT ws_web_site_sk, web_site_id, ws_item_sk, ws_order_number, ws_net_profit, d_year, cd_gender, profit_category, profit_rank FROM ( SELECT ws.ws_web_site_sk, ws_site.web_site_id, ws.ws_item_sk, ws.ws_order_number, ws.ws_net_profit, d_sold.d_year, cd.cd_gender, CASE WHEN ws.ws_net_profit >= 1000 THEN 'High' WHEN ws.ws_net_profit BETWEEN 500 AND 999.99 THEN 'Medium' ELSE 'Low' END AS profit_category, RANK() OVER (PARTITION BY ws.ws_web_site_sk, d_sold.d_year ORDER BY ws.ws_net_profit DESC) AS profit_rank FROM web_sales ws JOIN date_dim d_sold ON ws.ws_sold_date_sk = d_sold.d_date_sk JOIN web_site ws_site ON ws.ws_web_site_sk = ws_site.web_site_sk JOIN customer_demographics cd ON ws.ws_bill_cdemo_sk = cd.cd_demo_sk WHERE d_sold.d_year BETWEEN 2019 AND 2021 ) t WHERE profit_rank <= 5 ORDER BY ws_web_site_sk, d_year, profit_rank
